mapper.select:
SELECT *
FROM first_visit_form
WHERE id = #{formId}
  AND student_id = #{studentId}
  AND form_status = 'SUBMITTED'

SELECT *
FROM consent_record
WHERE form_id = #{formId}
  AND student_id = #{studentId}
  AND signed = 1
LIMIT 1

SELECT ds.id AS duty_schedule_id, ds.staff_id AS interviewer_id, su.real_name AS interviewer_name, ds.duty_date AS appointment_date, ds.slot_id, ts.slot_name, ts.start_time, ts.end_time, ds.room_id, cr.room_name, ds.capacity, ds.reserved_count, (ds.capacity - ds.reserved_count) AS remaining, CASE WHEN ds.status = 1 AND sp.status = 1 AND ds.staff_type = 'INTERVIEWER' AND ds.capacity > ds.reserved_count THEN TRUE ELSE FALSE END AS available, CASE WHEN ds.status != 1 THEN '该时间段已停用' WHEN sp.status != 1 THEN '初访员当前不可预约' WHEN ds.staff_type != 'INTERVIEWER' THEN '当前不是初访排班' WHEN ds.capacity <= ds.reserved_count THEN '该时间段已约满' ELSE NULL END AS disabled_reason FROM duty_schedule ds LEFT JOIN staff_profile sp ON ds.staff_id = sp.id LEFT JOIN sys_user su ON sp.user_id = su.id LEFT JOIN time_slot ts ON ds.slot_id = ts.id LEFT JOIN counseling_room cr ON ds.room_id = cr.id WHERE ds.duty_date = #{date} AND ds.staff_type = 'INTERVIEWER'
AND ds.staff_id = #{interviewerId}
ORDER BY ts.start_time ASC, ds.id ASC

SELECT COUNT(*)
FROM first_visit_appointment
WHERE appointment_date = #{date}

SELECT fva.id, fva.appointment_no, fva.form_id, fva.interviewer_id, su.real_name AS interviewer_name, fva.appointment_date, fva.slot_id, ts.slot_name, ts.start_time, ts.end_time, fva.room_id, cr.room_name, fva.appointment_status, fva.priority_flag, fva.audit_remark, fva.cancel_reason, fva.create_time, fva.update_time FROM first_visit_appointment fva LEFT JOIN staff_profile sp ON fva.interviewer_id = sp.id LEFT JOIN sys_user su ON sp.user_id = su.id LEFT JOIN time_slot ts ON fva.slot_id = ts.id LEFT JOIN counseling_room cr ON fva.room_id = cr.id WHERE fva.student_id = #{studentId}
AND fva.appointment_status = #{status}
ORDER BY fva.create_time DESC

SELECT COUNT(*)
FROM first_visit_appointment
WHERE student_id = #{studentId}

    AND appointment_status = #{status}

SELECT id, notify_type AS notifyType, title, content, create_time AS createTime FROM notification_log WHERE user_id = #{studentId}
AND notify_type = #{notifyType}
ORDER BY create_time DESC

SELECT COUNT(*)
FROM notification_log
WHERE user_id = #{studentId}

    AND notify_type = #{notifyType}
